import pickle
import json

class MockJSONDecodeError(json.JSONDecodeError):
    def __reduce__(self):
        return json.JSONDecodeError.__reduce__(self)

exc = MockJSONDecodeError("msg", "doc", 10)
pickled = pickle.dumps(exc)
unpickled = pickle.loads(pickled)
print(f"Unpickled: {unpickled}")
print(f"Type: {type(unpickled)}")
